public abstract class User {

	@Id
	@GeneratedValue(strategy = GenerationType.IDENTITY)
	@Column(name = "user_id")
	private Long userId;

@Embeddable
public class Credentials {

	@Column(name = "email", nullable = false, unique = true, length = 100)
	private String email;

	@Column(name = "password", nullable = false, length = 100)
	private String password;

@Entity
@Table(name = "reports")
public class Report {

	static final String STATUS_SUBMITTED = "submitted";
	static final String STATUS_ASSIGNED = "assigned";
	static final String STATUS_IN_PROGRESS = "in_progress";
	static final String STATUS_RESOLVED = "resolved";

	@Id
	@GeneratedValue(strategy = GenerationType.IDENTITY)
	@Column(name = "report_id")
	private Long reportId;

@Embeddable
public class Location {

	@Column(name = "city", nullable = false, length = 80)
	private String city;

	@Column(name = "cap", nullable = false, length = 5)
	private String cap;

	@Column(name = "street", nullable = false, length = 100)
	private String street;

	@Column(name = "street_number", nullable = false, length = 10)
	private String streetNumber;

	@Column(name = "municipal_area", nullable = false, length = 80)
	private String municipalArea;

public enum ReportCategory {

	BROKEN_STREETLIGHT("Broken Streetlight"),
	DAMAGED_ROAD("Damaged Road"),
	ABANDONED_WASTE("Abandoned Waste"),
	GENERAL_HAZARD("General Hazard"),
	DAMAGED_STREET_FURNITURE("Damaged Street Furniture");

@Entity
@Table(name = "status_updates")
public class StatusUpdate {

	@Id
	@GeneratedValue(strategy = GenerationType.IDENTITY)
	@Column(name = "update_id")
	private Long updateId;

@Entity
@Table(name = "internal_notes")
public class InternalNote {

	@Id
	@GeneratedValue(strategy = GenerationType.IDENTITY)
	@Column(name = "note_id")
	private Long noteId;

@Entity
@Table(name = "notifications")
public class Notification {

	/**
	 * Documents this component's behavior and responsibilities.
	 */
	private static final String STATUS_ASSIGNED = "assigned";

	/**
	 * Documents this component's behavior and responsibilities.
	 */
	private static final String STATUS_RESOLVED = "resolved";

	@Id
	@GeneratedValue(strategy = GenerationType.IDENTITY)
	@Column(name = "notification_id")
	private Long notificationId;

@Enumerated(EnumType.STRING)
	@Column(name = "category", nullable = false, length = 50)
	private ReportCategory category;

@ManyToOne(fetch = FetchType.LAZY)
	@JoinColumn(name = "citizen_id", nullable = false)
	private Citizen citizenReporting;

@ManyToOne(fetch = FetchType.LAZY)
	@JoinColumn(name = "operator_id")
	private MunicipalOperator operator;

@OneToMany(
			mappedBy = "report",
			cascade = CascadeType.ALL,
			fetch = FetchType.EAGER,
			orphanRemoval = true
	)
	private List<InternalNote> internalNotes = new ArrayList<>();

@ManyToOne(fetch = FetchType.LAZY)
	@JoinColumn(name = "report_id", nullable = false)
	private Report report;

@ManyToOne(fetch = FetchType.LAZY)
	@JoinColumn(name = "operator_id", nullable = false)
	private MunicipalOperator operator;

@ManyToOne(fetch = FetchType.LAZY)
	@JoinColumn(name = "operator_id", nullable = false)
	private MunicipalOperator operator;

@ManyToOne(fetch = FetchType.LAZY)
	@JoinColumn(name = "report_id", nullable = false)
	private Report report;

@ManyToOne
	@JoinColumn(name = "citizen_id", nullable = false)
	private Citizen destinatario;

@ManyToOne
	@JoinColumn(name = "report_id", nullable = false)
	private Report report;
